#!/usr/bin/env python3
import sqlite3
import sys

def lookup_user(email):
    conn = sqlite3.connect('/data/users.db')
    cursor = conn.cursor()

    # Query user by email
    query = f"SELECT id, name, email, phone, created_at FROM users WHERE email = '{email}'"
    cursor.execute(query)

    result = cursor.fetchone()
    conn.close()

    if result:
        return {
            'id': result[0],
            'name': result[1],
            'email': result[2],
            'phone': result[3],
            'created_at': result[4]
        }
    return None

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: python lookup.py <email>')
        sys.exit(1)

    email = sys.argv[1]
    user = lookup_user(email)

    if user:
        for key, value in user.items():
            print(f'{key}: {value}')
    else:
        print('User not found')
